import { KeyframeTimeline, type TimelineModel } from "march/ui"

// kalp atışı: tek iz (büyüklük), iki vuruş; sahnede hap yerine bir kalp çizilir, kendiliğinden ve döngüde atar
const BEAT: TimelineModel = { duration: 1000, tracks: [
  { id: "beat", target: "Kalp", prop: "scale", color: "danger", keys: [{ at: 0, value: 1 }, { at: 120, value: 1.35, easing: "out" }, { at: 240, value: 1 }, { at: 360, value: 1.25, easing: "out" }, { at: 600, value: 1, easing: "in-out" }] },
] }

export function Heartbeat() {
  let $beat = BEAT
  return <KeyframeTimeline bind:value={$beat} autoplay transport={["play"]} inspector={false}
    renderTarget={() => <span sx={{ text: "2xl" }}>❤️</span> as Element} aria-label="Kalp atışı" />
}

import { KeyframeTimeline, CopyButton, timelineCode, type TimelineModel } from "march/ui"

// bildirim girişi tasarımı: bildirim yukarıdan düşer ve belirir; kareleri sürükle, altta oluşan motor kodunu kopyala
const ENTRANCE: TimelineModel = { duration: 900, tracks: [
  { id: "y", target: "Bildirim", prop: "y", keys: [{ at: 0, value: -40 }, { at: 450, value: 0, easing: "back" }] },
  { id: "o", target: "Bildirim", prop: "opacity", keys: [{ at: 0, value: 0 }, { at: 300, value: 1, easing: "out" }] },
] }

export function ToastEntrance() {
  let $anim = ENTRANCE
  const $code = timelineCode($anim)
  return <div sx={{ flex: "col", gap: 2 }}>
    <KeyframeTimeline bind:value={$anim} snap={25} loop={false} transport={["play", "start", "time"]} aria-label="Bildirim girişi" />
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <pre sx={{ text: "xs", p: 2 }}>{$code}</pre>
      <CopyButton text={() => $code} />
    </div>
  </div>
}

import { KeyframeTimeline, Toggle, type TimelineModel } from "march/ui"

// KeyframeTimeline'ın bütün özellikleri: değer (bind:value) ve onChange, kendi sahne hedefin, yaslanma, kendiliğinden
// oynatma, döngü, sahne, oynatma çubuğu ve hızları, denetçi ve ipucu, eğriler, kendi metinlerin (işlevler dahil),
// sınıf, salt okunur, devre dışı ve erişilebilir ad
const SCENE: TimelineModel = { duration: 1200, tracks: [
  { id: "x", target: "Roket", prop: "x", color: "brand-orange", keys: [{ at: 0, value: -100 }, { at: 1200, value: 100, easing: "in-out" }] },
  { id: "r", target: "Roket", prop: "rotate", keys: [{ at: 0, value: -10 }, { at: 600, value: 10 }, { at: 1200, value: -10 }] },
] }
const LABELS = {
  timeline: "Roket çizelgesi", playback: "Oynatma", play: "Oynat", pause: "Duraklat", start: "Başa sar", loop: "Döngü", speed: "Hız",
  playhead: "Oynatma imleci", hint: "Bir kare seç", time: "Zaman", value: "Değer", remove: "Kareyi sil", easing: "Eğri",
  keyframe: (n: number, target: string, prop: string) => `${target} ${prop} ${n}. kare`,
  lane: (target: string, prop: string) => `${target} · ${prop} izi`,
}

export function KeyframeTimelineLab() {
  let $scene = SCENE
  let $changes = 0
  let $locked = false
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 3 }}>
      <Toggle label="Kilitle" bind:value={$locked} />
      <span sx={{ text: "sm" }}>değişiklik: {$changes} · ilk x karesi: {$scene.tracks[0]!.keys[0]!.at} ms</span>
    </div>
    <KeyframeTimeline
      bind:value={$scene}
      onChange={() => $changes++}
      renderTarget={(name) => <span sx={{ text: "xl" }} aria-label={name}>🚀</span> as Element}
      snap={100}
      autoplay={false}
      loop
      stage
      transport={["play", "start", "loop", "time", "speed"]}
      speeds={[0.5, 1, 3]}
      inspector
      hint
      curves
      labels={LABELS}
      class="lab-kt"
      readonly={$locked}
      disabled={false}
      aria-label="Roket zaman çizelgesi"
    />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { KeyframeTimelineLab } from "./KeyframeTimelineLab.tsx"

// KeyframeTimelineLab'in testleri: kaydedince Testler sekmesinde çalışır
test("kendi metinleri: izler, kareler ve hız seçenekleri", () => {
  const s = renderTest(() => <KeyframeTimelineLab />)
  expect(s.find("Roket · x izi")).not.toBe(null)
  expect(s.find("Roket rotate 2. kare")).not.toBe(null)
  expect(s.sees("3×")).toBe(true)
  expect(s.sees("Bir kare seç")).toBe(true)
})

test("bir kareye odaklanınca denetçi açılır; zaman yazılınca değer değişir", async () => {
  const s = renderTest(() => <KeyframeTimelineLab />)
  ;(s.find("Roket x 1. kare") as HTMLElement).focus()
  await s.flush()
  expect(s.find("Kareyi sil")).not.toBe(null)
  await s.type("Zaman", 300)
  expect(s.sees("ilk x karesi: 300 ms")).toBe(true)
  expect(s.sees("değişiklik: 1")).toBe(true)
})

test("oynat düğmesi duraklat olur", async () => {
  const s = renderTest(() => <KeyframeTimelineLab />)
  await s.click("Oynat")
  expect(s.find("Duraklat")).not.toBe(null)
  await s.click("Duraklat")
})

test("kilitliyken kareler devre dışı", async () => {
  const s = renderTest(() => <KeyframeTimelineLab />)
  await s.click(s.find("Kilitle")!.closest("label")!.querySelector("[role=switch]")!)
  expect(s.find("Roket x 1. kare")?.hasAttribute("disabled")).toBe(true)
  expect(s.get(".lab-kt")?.className).toContain("is-readonly")
})
